// Parse the GSTR-2B JSON downloaded from the GST portal into one row per B2B invoice
const item = $input.first();
const key = Object.keys(item.binary || {})[0];
if (!key) throw new Error('No file received. Upload the GSTR-2B JSON from the GST portal.');

const buf = await this.helpers.getBinaryDataBuffer(0, key);
let doc;
try { doc = JSON.parse(buf.toString('utf8')); }
catch (e) { throw new Error('This file is not valid JSON. Download the JSON version of GSTR-2B (not the Excel).'); }

const data = doc.data || doc;
const rp = String(data.rtnprd || '');                       // MMYYYY on the portal
const period = /^\d{6}$/.test(rp) ? `${rp.slice(2)}-${rp.slice(0, 2)}` : '';
if (!period) throw new Error('Could not read the return period (rtnprd) from the file.');

const docdata = data.docdata || {};
const n = v => { const x = parseFloat(v); return isNaN(x) ? 0 : x; };
const r2 = v => Math.round(v * 100) / 100;
const toISO = d => {
  const m = String(d || '').match(/^(\d{2})-(\d{2})-(\d{4})$/);
  return m ? `${m[3]}-${m[2]}-${m[1]}` : String(d || '');
};
const uploadedOn = $now.toISO();
const out = [];

const add = (sup, inv, section) => {
  const items = Array.isArray(inv.items) ? inv.items : [];
  const sum = f => (inv[f] !== undefined ? n(inv[f]) : items.reduce((s, it) => s + n(it[f]), 0));
  const gstin = String(sup.ctin || '').toUpperCase();
  const inum = String(inv.inum || '').trim();
  if (!gstin || !inum) return;
  out.push({
    json: {
      'Row Key': `${period}|${gstin}|${inum.toUpperCase()}`,
      'Return Period': period,
      'Section': section,
      'Supplier GSTIN': gstin,
      'Supplier Name': sup.trdnm || '',
      'Invoice Number': inum,
      'Invoice Date': toISO(inv.dt),
      'Invoice Value': r2(n(inv.val)),
      'Taxable Value': r2(sum('txval')),
      'IGST': r2(sum('igst')),
      'CGST': r2(sum('cgst')),
      'SGST': r2(sum('sgst')),
      'Cess': r2(sum('cess')),
      'ITC Available': String(inv.itcavl || 'Y').toUpperCase(),
      'Reason': inv.rsn || '',
      'Supplier Filing Date': toISO(sup.supfildt),
      'Uploaded On': uploadedOn,
    },
  });
};

for (const sup of docdata.b2b || []) for (const inv of sup.inv || []) add(sup, inv, 'B2B');
for (const sup of docdata.b2ba || []) for (const inv of sup.inv || []) add(sup, inv, 'B2BA');

if (!out.length) throw new Error(`No B2B invoices found in GSTR-2B for ${period}.`);
return out;

// Collapse the uploaded rows into one run so the reconciliation starts once
const rows = $('Parse GSTR-2B JSON').all();
return [{
  json: {
    returnPeriod: rows[0].json['Return Period'],
    source: 'GSTR-2B upload',
    rowsLoaded: rows.length,
  },
}];

// Load past results once: skip PDFs already processed in earlier periods
// and count open items that will be carried forward
const cfg = $('Set Recon Rules1').first().json;
const FLAGS = ['Missing in GSTR-2B', 'Tax Mismatch', 'GSTIN Issue', 'Billed to Wrong GSTIN', 'Wrong Tax Type', 'ITC Blocked in GSTR-2B'];
const hist = $input.all().map(i => i.json).filter(r => r['Recon Key']);

const processedSources = [...new Set(
  hist.filter(r => r['Source'] && String(r['Return Period']) !== cfg.returnPeriod).map(r => String(r['Source']))
)];
const openCarryForward = hist.filter(r =>
  FLAGS.includes(r['Status']) && String(r['Return Period']) < cfg.returnPeriod
).length;

return [{ json: { ...cfg, processedSources, historyRows: hist.length, openCarryForward } }];

// One item per new PDF attachment, keeping sender and thread details.
// PDFs already reconciled in an earlier period are skipped to save AI calls.
const ctx = $('Build Run Context').first().json;
const skip = new Set(ctx.processedSources || []);
const out = [];

$input.all().forEach((item, i) => {
  const j = item.json;
  const from = (j.from && j.from.value && j.from.value[0]) || {};
  for (const bin of Object.values(item.binary || {})) {
    const name = String(bin.fileName || '').toLowerCase();
    if (bin.mimeType !== 'application/pdf' && !name.endsWith('.pdf')) continue;
    const source = `${j.id}|${bin.fileName}`;
    if (skip.has(source)) continue;
    out.push({
      json: {
        source,
        messageId: j.id,
        threadId: j.threadId,
        subject: j.subject || '',
        receivedAt: j.date,
        senderEmail: from.address || '',
        senderName: from.name || '',
        fileName: bin.fileName,
      },
      binary: { data: bin },
      pairedItem: { item: i },
    });
  }
});
return out;

// Validate AI output: GSTIN checksum, tax arithmetic, tax type vs place of supply,
// extraction confidence. Anything unreliable goes to manual review instead of being guessed.
const cfg = $('Set Recon Rules1').first().json;
const minConf = Number(cfg.minConfidence) || 0.75;
const CH = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ';
const GSTIN_RE = /^\d{2}[A-Z]{5}\d{4}[A-Z][1-9A-Z]Z[0-9A-Z]$/;

// Official GSTIN check digit (mod 36)
const gstinValid = g => {
  if (!GSTIN_RE.test(g)) return false;
  let sum = 0;
  for (let i = 0; i < 14; i++) {
    const p = CH.indexOf(g[i]) * (i % 2 === 0 ? 1 : 2);
    sum += Math.floor(p / 36) + (p % 36);
  }
  return CH[(36 - (sum % 36)) % 36] === g[14];
};
const num = v => {
  const n = parseFloat(String(v ?? '').replace(/[^0-9.\-]/g, ''));
  return isNaN(n) ? 0 : Math.round(n * 100) / 100;
};
const normG = s => String(s || '').toUpperCase().replace(/\s/g, '');
const ourGSTIN = normG(cfg.companyGSTIN);
const seen = new Set();
const out = [];

$input.all().forEach((item, i) => {
  const meta = $('Split & Skip Processed PDFs').itemMatching(i).json;
  const text = String($('Read PDF Text1').itemMatching(i).json.text || '');
  let f = item.json.message && item.json.message.content;
  if (typeof f === 'string') { try { f = JSON.parse(f); } catch (e) { f = null; } }

  const base = {
    source: meta.source, messageId: meta.messageId, threadId: meta.threadId,
    fileName: meta.fileName, vendorEmail: meta.senderEmail,
  };
  const review = reason => out.push({
    json: {
      ...base, needsReview: true, reviewReason: reason,
      vendorName: (f && f.vendorName) || meta.senderName || meta.senderEmail,
      vendorGSTIN: normG(f && f.vendorGSTIN), invoiceNumber: String((f && f.invoiceNumber) || ''),
      invoiceDate: (f && f.invoiceDate) || '', totalTax: num(f && f.totalTax),
    },
    pairedItem: { item: i },
  });

  if (text.trim().length < 40) return review('Scanned or image-only PDF, no text layer to read');
  if (item.json.error || !f) return review('AI extraction failed, check the PDF manually');
  if (f.isTaxInvoice === false) return;                 // quotes, proformas, credit notes
  if (!f.invoiceNumber) return review('Invoice number not readable');
  const conf = Number(f.confidence);
  if (!isNaN(conf) && conf < minConf) return review(`Low extraction confidence (${conf})`);

  const gstin = normG(f.vendorGSTIN);
  const invoiceNumber = String(f.invoiceNumber).trim();
  const key = `${gstin}|${invoiceNumber.toUpperCase()}`;
  if (seen.has(key)) return;                             // same invoice attached twice
  seen.add(key);

  const igst = num(f.igst), cgst = num(f.cgst), sgst = num(f.sgst), cess = num(f.cess);
  const componentTax = Math.round((igst + cgst + sgst + cess) * 100) / 100;
  const statedTax = num(f.totalTax);
  if (statedTax && Math.abs(statedTax - componentTax) > 1) {
    return review(`Tax components (${componentTax}) do not add up to total tax (${statedTax})`);
  }
  if (cgst !== sgst && Math.abs(cgst - sgst) > 1) return review('CGST and SGST differ, check the invoice');

  // Intra-state supply must carry CGST+SGST, inter-state must carry IGST
  const buyer = normG(f.buyerGSTIN) || ourGSTIN;
  let taxTypeIssue = '';
  if (cfg.checkTaxType && gstinValid(gstin) && /^\d{2}/.test(buyer)) {
    const intra = gstin.slice(0, 2) === buyer.slice(0, 2);
    if (intra && igst > 0 && cgst + sgst === 0) taxTypeIssue = 'IGST charged on an intra-state supply';
    if (!intra && cgst + sgst > 0 && igst === 0) taxTypeIssue = 'CGST/SGST charged on an inter-state supply';
  }

  out.push({
    json: {
      ...base,
      needsReview: false,
      vendorName: f.vendorName || meta.senderName || meta.senderEmail,
      vendorGSTIN: gstin,
      gstinValid: gstinValid(gstin),
      buyerGSTIN: normG(f.buyerGSTIN),
      invoiceNumber,
      invoiceDate: f.invoiceDate || '',
      taxableValue: num(f.taxableValue),
      igst, cgst, sgst, cess,
      totalTax: componentTax || statedTax,
      totalAmount: num(f.totalAmount),
      taxTypeIssue,
      confidence: isNaN(conf) ? null : conf,
    },
    pairedItem: { item: i },
  });
});
return out;

// One reminder per vendor with an escalation tier based on the follow-up history
const cfg = $('Set Recon Rules1').first().json;
const rows = $('Reconcile Against GSTR-2B1').all().map(i => i.json);
const approval = $('Request Send Approval').first().json || {};
const approved = !!(approval.data && approval.data.approved === true);
const todayISO = $today.toISODate();
const inr = n => 'Rs. ' + Number(n || 0).toLocaleString('en-IN', { maximumFractionDigits: 2 });

const log = {};
for (const r of $input.all().map(i => i.json)) {
  if (r['Vendor GSTIN']) log[String(r['Vendor GSTIN']).toUpperCase()] = r;
}

const vendors = {};
for (const r of rows) {
  if (!r.isFlagged || r.status === 'ITC Time-barred' || !r.vendorEmail || !r.messageId) continue;
  const key = r.vendorGSTIN || r.vendorEmail;
  const v = vendors[key] || (vendors[key] = {
    vendorName: r.vendorName, vendorGSTIN: r.vendorGSTIN, vendorEmail: r.vendorEmail,
    messageId: r.messageId, threadId: r.threadId, totalItcAtRiskValue: 0,
    current: [], carried: [], critical: false, nearestDeadline: '',
  });
  v.totalItcAtRiskValue += r.itcAtRisk;
  if (r.priority === 'Critical') {
    v.critical = true;
    if (!v.nearestDeadline || r.itcDeadline < v.nearestDeadline) v.nearestDeadline = r.itcDeadline;
  }
  const line = `- Invoice ${r.invoiceNumber} dated ${r.invoiceDate}: ${r.status}, tax ${inr(r.bookTax)}` +
    (r.status === 'Tax Mismatch' ? ` (GSTR-2B shows ${inr(r.twoBTax)})` : '') +
    (r.status === 'Wrong Tax Type' ? ` (${r.action.split(',')[0]})` : '');
  (r.carriedForward === 'Yes' ? v.carried : v.current).push(line);
}

const TIERS = ['', 'Friendly reminder', 'Firm follow-up', 'Final notice - payment on hold'];
return Object.values(vendors)
  .map(v => {
    const prev = log[String(v.vendorGSTIN).toUpperCase()] || {};
    const prevCount = parseInt(prev['Reminder Count'], 10) || 0;
    const sameDayRerun = String(prev['Last Reminded'] || '') === todayISO;
    const reminderCount = sameDayRerun ? Math.max(prevCount, 1) : prevCount + 1;
    let tier = Math.min(reminderCount, 3);
    if (v.critical && tier < 2) tier = 2;
    return {
      json: {
        ...v,
        totalItcAtRiskValue: Math.round(v.totalItcAtRiskValue * 100) / 100,
        totalItcAtRisk: inr(v.totalItcAtRiskValue),
        invoiceCount: v.current.length + v.carried.length,
        issueList: v.current.join('\n') || 'None this period',
        carriedList: v.carried.join('\n') || 'None',
        reminderCount,
        tier,
        tierLabel: TIERS[tier],
        sendMode: approved ? 'send' : 'draft',
        lastReminded: todayISO,
        period: cfg.returnPeriod,
      },
    };
  })
  .sort((a, b) => b.json.totalItcAtRiskValue - a.json.totalItcAtRiskValue);

