// Payment-hold recommendation for vendors that ignored earlier reminders
const cfg = $('Set Recon Rules1').first().json;
const list = $input.all().map(i => i.json);
const inr = n => '\u20b9' + Number(n || 0).toLocaleString('en-IN', { maximumFractionDigits: 2 });
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const td = 'style="padding:6px 8px;border-bottom:1px solid #eee"';
const total = list.reduce((s, v) => s + v.totalItcAtRiskValue, 0);

const html = `<div style="font-family:Arial,sans-serif;max-width:680px;color:#222">
<h2>Payment hold recommended - ${list.length} vendor(s)</h2>
<p>These vendors have received ${'3'}+ reminders and their GSTR-1 is still not fixed. Consider holding the GST portion
of pending payments (${inr(total)} ITC at risk) until the invoices show up correctly in GSTR-2B.</p>
<table style="border-collapse:collapse;width:100%">
<tr style="background:#f5f5f5"><th align="left" ${td}>Vendor</th><th align="left" ${td}>Reminders</th><th align="right" ${td}>ITC at risk</th></tr>
${list.map(v => `<tr><td ${td}>${esc(v.vendorName)}<br><span style="color:#777;font-size:12px">${esc(v.vendorGSTIN)} · ${esc(v.vendorEmail)}</span></td>
<td ${td}>${v.reminderCount}</td><td ${td} align="right">${inr(v.totalItcAtRiskValue)}</td></tr>`).join('')}
</table></div>`;

return [{ json: { subject: `Payment hold recommended: ${list.length} vendor(s), ${inr(total)} ITC at risk (${cfg.returnPeriodLabel})`, html } }];

