// Reconcile this period's invoices AND open items from earlier periods against GSTR-2B.
// Adds fuzzy invoice-number matching, ITC availability, Section 16(4) deadlines and priority.
const cfg = $('Set Recon Rules1').first().json;
const period = cfg.returnPeriod;
const tol = Number(cfg.taxTolerance) || 0;
const warnDays = Number(cfg.deadlineWarningDays) || 60;
const highValue = Number(cfg.highValueThreshold) || 25000;
const todayISO = $today.toISODate();
const FLAGS = ['Missing in GSTR-2B', 'Tax Mismatch', 'GSTIN Issue', 'Billed to Wrong GSTIN', 'Wrong Tax Type', 'ITC Blocked in GSTR-2B'];

const num = v => { const n = parseFloat(String(v ?? '').replace(/[^0-9.\-]/g, '')); return isNaN(n) ? 0 : n; };
const r2 = n => Math.round(n * 100) / 100;
const normNo = s => String(s || '').toUpperCase().replace(/[^A-Z0-9]/g, '').replace(/^0+/, '');
const normG = s => String(s || '').toUpperCase().replace(/\s/g, '');
const ourGSTIN = normG(cfg.companyGSTIN);
const checkOurGSTIN = /^\d{2}[A-Z]{5}\d{4}[A-Z][1-9A-Z]Z[0-9A-Z]$/.test(ourGSTIN);

const lev = (a, b) => {
  const d = Array.from({ length: a.length + 1 }, (_, i) => [i, ...Array(b.length).fill(0)]);
  for (let j = 1; j <= b.length; j++) d[0][j] = j;
  for (let i = 1; i <= a.length; i++) for (let j = 1; j <= b.length; j++)
    d[i][j] = Math.min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
  return d[a.length][b.length];
};

// Section 16(4): ITC must be claimed by 30 Nov after the end of the invoice's financial year
const deadlineOf = d => {
  const dt = DateTime.fromISO(String(d || ''));
  if (!dt.isValid) return null;
  return DateTime.fromObject({ year: dt.month >= 4 ? dt.year + 1 : dt.year, month: 11, day: 30 });
};

const invoices = $('Validate & Normalize Invoices').all().map(i => i.json);
const history = $('Read Reconciliation History').all().map(i => i.json).filter(r => r['Recon Key']);
const histByKey = Object.fromEntries(history.map(r => [String(r['Recon Key']), r]));

// GSTR-2B rows up to this period (rows pasted without a period count as this period)
const rows = $input.all().map(i => i.json).filter(r => r['Supplier GSTIN']).map((r, idx) => ({
  idx,
  period: String(r['Return Period'] || period),
  gstin: normG(r['Supplier GSTIN']),
  no: normNo(r['Invoice Number']),
  rawNo: String(r['Invoice Number']),
  name: r['Supplier Name'] || '',
  date: r['Invoice Date'] || '',
  tax: r2(num(r['IGST']) + num(r['CGST']) + num(r['SGST']) + num(r['Cess'])),
  itcAvailable: String(r['ITC Available'] || 'Y').toUpperCase() !== 'N',
  reason: r['Reason'] || '',
})).filter(r => r.period <= period);

const byKey = {};
for (const r of rows) {
  const k = `${r.gstin}|${r.no}`;
  if (!byKey[k] || byKey[k].period < r.period) byKey[k] = r;   // amendments: latest wins
}
const used = new Set();

const finish = (b, s) => {
  const deadline = deadlineOf(b.invoiceDate);
  const days = deadline ? Math.floor(deadline.diff($today, 'days').days) : null;
  const flagged = FLAGS.includes(s.status);
  let status = s.status, action = s.action;
  if (flagged && days !== null && days < 0) {
    status = 'ITC Time-barred';
    action = 'Section 16(4) deadline has passed, ITC can no longer be claimed';
  }
  let priority = 'Normal';
  if (status === 'ITC Time-barred') priority = 'Lapsed';
  else if (flagged && days !== null && days <= warnDays) priority = 'Critical';
  else if (flagged && s.itcAtRisk >= highValue) priority = 'High';
  const key = s.reconKey;
  const prev = histByKey[key];
  return {
    json: {
      reconKey: key,
      returnPeriod: s.returnPeriod || period,
      lastCheckedPeriod: period,
      vendorName: b.vendorName || '',
      vendorGSTIN: normG(b.vendorGSTIN),
      vendorEmail: b.vendorEmail || '',
      messageId: b.messageId || '',
      threadId: b.threadId || '',
      source: b.source || '',
      invoiceNumber: b.invoiceNumber || '',
      invoiceDate: b.invoiceDate || '',
      bookTax: r2(num(b.totalTax)),
      twoBTax: s.match ? s.match.tax : 0,
      twoBInvoiceNumber: s.match ? s.match.rawNo : '',
      difference: r2(num(b.totalTax) - (s.match ? s.match.tax : 0)),
      itcAtRisk: r2(s.itcAtRisk || 0),
      status,
      action,
      priority,
      itcDeadline: deadline ? deadline.toISODate() : '',
      daysToDeadline: days,
      carriedForward: s.carried ? 'Yes' : 'No',
      firstFlagged: flagged ? ((prev && prev['First Flagged']) || todayISO) : ((prev && prev['First Flagged']) || ''),
      isFlagged: flagged || status === 'ITC Time-barred',
      checkedOn: todayISO,
    },
  };
};

const evaluate = b => {
  const gstin = normG(b.vendorGSTIN);
  const tax = r2(num(b.totalTax));
  if (b.needsReview) return { status: 'Needs Manual Review', action: b.reviewReason, itcAtRisk: 0 };
  if (!b.gstinValid) return { status: 'GSTIN Issue', action: 'Supplier GSTIN is invalid or fails the check digit, ask for a corrected invoice', itcAtRisk: tax };
  if (checkOurGSTIN && b.buyerGSTIN && b.buyerGSTIN !== ourGSTIN)
    return { status: 'Billed to Wrong GSTIN', action: `Ask vendor to amend the invoice to our GSTIN ${ourGSTIN}`, itcAtRisk: tax };
  if (b.taxTypeIssue) return { status: 'Wrong Tax Type', action: `${b.taxTypeIssue}, ask vendor to issue a corrected invoice`, itcAtRisk: tax };

  const no = normNo(b.invoiceNumber);
  let match = byKey[`${gstin}|${no}`];
  let fuzzy = false;
  if (!match || used.has(match.idx)) {
    // Same supplier, tax within tolerance, invoice number close or same date
    const cands = rows
      .filter(r => !used.has(r.idx) && r.gstin === gstin && Math.abs(r.tax - tax) <= tol)
      .map(r => ({ r, d: lev(r.no, no) }))
      .filter(c => c.d <= 3 || c.r.date === b.invoiceDate)
      .sort((a, c) => a.d - c.d);
    match = cands.length ? cands[0].r : null;
    fuzzy = !!match;
  }
  if (!match) return { status: 'Missing in GSTR-2B', action: 'Ask vendor to report this invoice in GSTR-1 / IFF', itcAtRisk: tax };
  used.add(match.idx);
  if (!match.itcAvailable)
    return { match, status: 'ITC Blocked in GSTR-2B', action: `GSTR-2B marks ITC as not available${match.reason ? ' (' + match.reason + ')' : ''}`, itcAtRisk: tax };
  const diff = r2(tax - match.tax);
  if (Math.abs(diff) > tol) return { match, status: 'Tax Mismatch', action: 'Ask vendor to check and amend tax reported in GSTR-1', itcAtRisk: Math.max(diff, 0) };
  if (fuzzy) return { match, status: 'Matched (invoice no. differs)', action: `Verify: GSTR-2B shows invoice ${match.rawNo}`, itcAtRisk: 0 };
  return { match, status: 'Matched', action: 'None', itcAtRisk: 0 };
};

const out = [];
const doneKeys = new Set();

// 1) Invoices from the mailbox dated up to this period
for (const b of invoices) {
  const ip = String(b.invoiceDate || '').slice(0, 7);
  if (!b.needsReview && ip && ip > period) continue;   // next period's invoice, handled next run
  const s = evaluate(b);
  s.reconKey = b.needsReview ? `REVIEW|${b.source}` : `${normG(b.vendorGSTIN) || 'NOGSTIN'}|${normNo(b.invoiceNumber)}`;
  const prev = histByKey[s.reconKey];
  s.returnPeriod = (prev && prev['Return Period']) || period;
  doneKeys.add(s.reconKey);
  out.push(finish(b, s));
}

// 2) Open items from earlier periods: did the vendor report them late?
for (const h of history) {
  const key = String(h['Recon Key']);
  if (doneKeys.has(key) || !FLAGS.includes(h['Status']) || String(h['Return Period']) >= period) continue;
  const b = {
    vendorName: h['Vendor Name'], vendorGSTIN: h['Vendor GSTIN'], vendorEmail: h['Vendor Email'],
    messageId: h['Message ID'], threadId: h['Thread ID'], source: h['Source'],
    invoiceNumber: h['Invoice Number'], invoiceDate: h['Invoice Date'], totalTax: num(h['Book Tax']),
  };
  let s = { status: h['Status'], action: h['Action'], itcAtRisk: num(h['ITC at Risk']) };
  if (['Missing in GSTR-2B', 'Tax Mismatch'].includes(h['Status'])) {
    const m = byKey[`${normG(b.vendorGSTIN)}|${normNo(b.invoiceNumber)}`];
    if (m && !used.has(m.idx) && m.itcAvailable && Math.abs(m.tax - b.totalTax) <= tol) {
      used.add(m.idx);
      s = { match: m, status: 'Resolved in Later GSTR-2B', action: `Reported in ${m.period} GSTR-2B, claim ITC in this GSTR-3B`, itcAtRisk: 0 };
    }
  }
  s.reconKey = key;
  s.returnPeriod = String(h['Return Period']);
  s.carried = s.status !== 'Resolved in Later GSTR-2B';
  out.push(finish(b, s));
}

// 3) This period's GSTR-2B entries with no invoice in the mailbox
for (const r of rows) {
  if (used.has(r.idx) || r.period !== period) continue;
  const b = { vendorName: r.name, vendorGSTIN: r.gstin, invoiceNumber: r.rawNo, invoiceDate: r.date, totalTax: 0 };
  out.push(finish(b, {
    reconKey: `${r.gstin}|${r.no}`, returnPeriod: period, match: r, itcAtRisk: 0,
    status: 'In GSTR-2B, Not in Mailbox',
    action: r.itcAvailable ? 'Locate the invoice copy before claiming ITC' : 'Locate invoice; 2B also marks ITC unavailable',
  }));
}
return out;

// One summary email for the accounts team
const cfg = $('Set Recon Rules1').first().json;
const rows = $('Reconcile Against GSTR-2B1').all().map(i => i.json);
const inr = n => '\u20b9' + Number(n || 0).toLocaleString('en-IN', { maximumFractionDigits: 2 });
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const td = 'style="padding:6px 8px;border-bottom:1px solid #eee;vertical-align:top"';
const PCOLOR = { Lapsed: '#7f1d1d', Critical: '#b91c1c', High: '#c2410c', Normal: '#555' };

const counts = {};
for (const r of rows) counts[r.status] = (counts[r.status] || 0) + 1;
const flagged = rows.filter(r => r.isFlagged).sort((a, b) => b.itcAtRisk - a.itcAtRisk);
const current = flagged.filter(r => r.carriedForward !== 'Yes');
const carried = flagged.filter(r => r.carriedForward === 'Yes');
const resolved = rows.filter(r => r.status === 'Resolved in Later GSTR-2B');
const review = rows.filter(r => r.status === 'Needs Manual Review');
const notInMail = rows.filter(r => r.status === 'In GSTR-2B, Not in Mailbox');
const critical = flagged.filter(r => ['Critical', 'Lapsed'].includes(r.priority));
const totalRisk = flagged.reduce((s, r) => s + r.itcAtRisk, 0);
const recovered = resolved.reduce((s, r) => s + r.bookTax, 0);
const chase = new Set(flagged.filter(r => r.vendorEmail && r.messageId && r.status !== 'ITC Time-barred').map(r => r.vendorGSTIN || r.vendorEmail));

const table = (list, cols) => list.length ? `<table style="border-collapse:collapse;width:100%;margin-bottom:18px">
<tr style="background:#f5f5f5">${cols.map(c => `<th align="left" ${td}>${c[0]}</th>`).join('')}</tr>
${list.map(r => `<tr>${cols.map(c => `<td ${td}>${c[1](r)}</td>`).join('')}</tr>`).join('')}</table>` : '<p style="color:#777">None.</p>';

const vendorCell = r => `${esc(r.vendorName)}<br><span style="color:#777;font-size:12px">${esc(r.vendorGSTIN)}</span>`;
const prioCell = r => `<b style="color:${PCOLOR[r.priority] || '#555'}">${esc(r.priority)}</b>${r.daysToDeadline !== null && r.daysToDeadline !== '' ? `<br><span style="font-size:12px;color:#777">${r.daysToDeadline} days to ${esc(r.itcDeadline)}</span>` : ''}`;

const html = `<div style="font-family:Arial,sans-serif;max-width:760px;color:#222">
<h2 style="margin-bottom:4px">GST reconciliation - ${esc(cfg.returnPeriodLabel)}</h2>
<p style="color:#777;margin-top:0">Run source: ${esc(cfg.runSource)}</p>
<p><b>${inr(totalRisk)}</b> of input tax credit is at risk across <b>${flagged.length}</b> invoice(s).
${critical.length ? `<b style="color:#b91c1c">${critical.length} are critical or past the Section 16(4) deadline.</b>` : ''}
${resolved.length ? `<br>${resolved.length} earlier item(s) were reported late and are now claimable (${inr(recovered)}).` : ''}</p>
<p>${chase.size} vendor reminder(s) are ready. A separate approval email lets you send them or keep them as drafts.</p>
<table style="border-collapse:collapse;margin-bottom:18px">${Object.entries(counts).map(([k, v]) => `<tr><td ${td}>${esc(k)}</td><td ${td}>${v}</td></tr>`).join('')}</table>
<h3>This period's issues</h3>
${table(current, [['Vendor', vendorCell], ['Invoice', r => esc(r.invoiceNumber)], ['Issue', r => esc(r.status)], ['Priority', prioCell], ['ITC at risk', r => inr(r.itcAtRisk)]])}
<h3>Still open from earlier periods</h3>
${table(carried, [['Vendor', vendorCell], ['Invoice', r => `${esc(r.invoiceNumber)}<br><span style="font-size:12px;color:#777">${esc(r.returnPeriod)}</span>`], ['Issue', r => esc(r.status)], ['Priority', prioCell], ['ITC at risk', r => inr(r.itcAtRisk)]])}
<h3>Needs manual review</h3>
${table(review, [['File / vendor', r => esc(r.vendorName || r.source)], ['Reason', r => esc(r.action)]])}
<h3>In GSTR-2B but no invoice in the mailbox</h3>
${table(notInMail, [['Vendor', vendorCell], ['Invoice', r => esc(r.invoiceNumber)], ['2B tax', r => inr(r.twoBTax)]])}
<p style="color:#777;font-size:12px">Full detail is in the Reconciliation and Manual Review tabs.</p></div>`;

return [{
  json: {
    subject: `GST reconciliation ${cfg.returnPeriodLabel}: ${inr(totalRisk)} ITC at risk${critical.length ? ` (${critical.length} critical)` : ''}`,
    html,
    vendorsToChase: chase.size,
    totalRiskLabel: inr(totalRisk),
    criticalCount: critical.length,
  },
}];
